import itertools

names = ["Peter", "Eric", "Alice", "Arnold"]
smoothies = ["watermelon", "desert", "cherry", "dragonfruit"]
colors = ["green", "white", "red", "yellow"]

def satisfies(name, smoothie, color):
    if smoothie[1] != "cherry":
        return False
    if smoothie[3] != "dragonfruit":
        return False
    if color[0] != "white":
        return False
    if color[3] != "red":
        return False

    for i in range(4):
        if (name[i] == "Eric") != (smoothie[i] == "dragonfruit"):
            return False
        if (name[i] == "Arnold") != (smoothie[i] == "watermelon"):
            return False
        if (color[i] == "yellow") != (smoothie[i] == "watermelon"):
            return False
        if (name[i] == "Peter") != (color[i] == "white"):
            return False

    return True

for name in itertools.permutations(names):
    for smoothie in itertools.permutations(smoothies):
        for color in itertools.permutations(colors):
            if satisfies(name, smoothie, color):
                for i in range(4):
                    print(f"House {i + 1}: {name[i]}, {smoothie[i]}, {color[i]}")
                raise SystemExit

import itertools


def main():
    names = ["Eric", "Arnold", "Peter"]
    cars = ["ford f150", "tesla model 3", "toyota camry"]
    vacations = ["beach", "mountain", "city"]
    nationalities = ["dane", "swede", "brit"]
    hairs = ["blonde", "black", "brown"]
    styles = ["colonial", "ranch", "victorian"]

    def local_ok(profile):
        name, car, vacation, nationality, hair, style = profile

        if (nationality == "swede") != (car == "ford f150"):
            return False

        black = hair == "black"
        arnold = name == "Arnold"
        dane = nationality == "dane"
        beach = vacation == "beach"
        if not (black == arnold == dane == beach):
            return False

        if (style == "colonial") != (hair == "blonde"):
            return False

        if (name == "Peter") != (vacation == "city"):
            return False

        return True

    profiles = [
        profile
        for profile in itertools.product(
            names, cars, vacations, nationalities, hairs, styles
        )
        if local_ok(profile)
    ]

    def find_house(houses, category, value):
        for i, profile in enumerate(houses):
            if profile[category] == value:
                return i
        return -1

    def global_ok(houses):
        for category in range(6):
            if len({profile[category] for profile in houses}) != 3:
                return False

        if houses[1][4] == "blonde":
            return False

        if houses[1][5] == "victorian":
            return False

        toyota_house = find_house(houses, 1, "toyota camry")
        arnold_house = find_house(houses, 0, "Arnold")
        if abs(toyota_house - arnold_house) != 1:
            return False

        black_house = find_house(houses, 4, "black")
        ranch_house = find_house(houses, 5, "ranch")
        if not (black_house > ranch_house):
            return False

        peter_house = find_house(houses, 0, "Peter")
        beach_house = find_house(houses, 2, "beach")
        if peter_house + 1 != beach_house:
            return False

        return True

    for house1 in profiles:
        for house2 in profiles:
            for house3 in profiles:
                houses = (house1, house2, house3)
                if global_ok(houses):
                    for i, profile in enumerate(houses, 1):
                        print(
                            f"House {i}: {profile[0]}, {profile[1]}, "
                            f"{profile[2]}, {profile[3]}, {profile[4]}, {profile[5]}"
                        )
                    return


if __name__ == "__main__":
    main()

