    drinks = ["water", "tea", "milk", "coffee"]

    for name_assign in itertools.permutations(names):
        name_pos = {name: pos for pos, name in enumerate(name_assign)}

        # Clue 4: Eric is in the third house.
        if name_pos["Eric"] != 2:
            continue

        # Clue 5: Arnold is somewhere to the right of Alice.
        if not name_pos["Arnold"] > name_pos["Alice"]:
            continue

        for style_assign in itertools.permutations(styles):
            style_pos = {style: pos for pos, style in enumerate(style_assign)}

            # Clue 3: Ranch is somewhere to the left of Craftsman.
            if not style_pos["ranch"] < style_pos["craftsman"]:
                continue

            # Clue 6: The person in a ranch-style home is Arnold.
            if name_assign[style_pos["ranch"]] != "Arnold":
                continue

            # Clue 7: Eric and the person residing in a Victorian house are next to each other.
            if abs(name_pos["Eric"] - style_pos["victorian"]) != 1:
                continue

            for drink_assign in itertools.permutations(drinks):
                drink_pos = {drink: pos for pos, drink in enumerate(drink_assign)}

                # Clue 1: Eric is the one who only drinks water.
                if drink_assign[name_pos["Eric"]] != "water":
                    continue

                # Clue 2: The person who likes milk is the person residing in a Victorian house.
