styles = ("colonial", "victorian")
lunches = ("grilled cheese", "pizza")
sports = ("basketball", "soccer")
children = ("Bella", "Fred")


def is_valid(name, music, style, lunch, sport, child):
    for h in range(2):
        if (style[h] == "colonial") != (lunch[h] == "pizza"):
            return False
        if (style[h] == "colonial") != (music[h] == "pop"):
            return False
        if (style[h] == "colonial") != (name[h] == "Arnold"):
            return False
        if (name[h] == "Eric") != (sport[h] == "soccer"):
            return False
        if (lunch[h] == "grilled cheese") != (child[h] == "Bella"):
            return False

    return lunch[1] != "pizza"


def solve():
    for name in itertools.permutations(names):
        for music in itertools.permutations(musics):
            for style in itertools.permutations(styles):
                for lunch in itertools.permutations(lunches):
                    for sport in itertools.permutations(sports):
                        for child in itertools.permutations(children):
