import itertools

NAMES = ["Peter", "Arnold", "Eric", "Carol", "Alice", "Bob"]
MUSIC = ["country", "classical", "pop", "hip hop", "jazz", "rock"]
STYLES = ["modern", "mediterranean", "victorian", "craftsman", "ranch", "colonial"]
PHONES = ["huawei p50", "iphone 13", "google pixel 6", "oneplus 9", "xiaomi mi 11", "samsung galaxy s21"]
PETS = ["hamster", "dog", "cat", "rabbit", "fish", "bird"]


def names_ok(names):
    if names[1] != "Peter":
        return False
    if abs(names.index("Carol") - names.index("Peter")) != 1:
        return False
    if abs(names.index("Carol") - names.index("Alice")) != 3:
        return False
    return True


def styles_ok(styles, names):
    if styles[names.index("Arnold")] != "victorian":
        return False
    if styles[names.index("Carol")] != "craftsman":
        return False
    if styles[names.index("Peter")] != "colonial":
        return False
    if styles[names.index("Eric")] != "modern":
        return False
    return True


def music_ok(music, styles):
    if music[styles.index("colonial")] != "rock":
        return False
    if not music.index("pop") < styles.index("colonial"):
        return False
    if not styles.index("ranch") < music.index("classical"):
        return False
    return True


def phones_ok(phones, names, styles, music):
    if phones[names.index("Peter")] != "oneplus 9":
        return False
    if phones[styles.index("modern")] != "samsung galaxy s21":
        return False
    if music[phones.index("samsung galaxy s21")] != "hip hop":
        return False
    if phones.index("google pixel 6") + 1 != phones.index("xiaomi mi 11"):
        return False
    if abs(phones.index("huawei p50") - music.index("country")) != 1:
        return False
    return True


def pets_ok(pets, styles, phones):
    if pets[5] != "rabbit":
        return False
    if pets[4] != "dog":
        return False
    if pets.index("hamster") == 0:
        return False
    if pets.index("cat") == 3:
        return False
    if pets.index("cat") != styles.index("mediterranean"):
        return False
    if pets.index("bird") != phones.index("google pixel 6"):
        return False
    return True


def valid_solution(names, styles, music, phones, pets):
    if names[1] != "Peter":
        return False
    if pets.index("cat") != styles.index("mediterranean"):
        return False
    if styles.index("modern") != phones.index("samsung galaxy s21"):
        return False
    if pets.index("bird") != phones.index("google pixel 6"):
        return False
    if pets.index("bird") + 1 != phones.index("xiaomi mi 11"):
        return False
    if names.index("Arnold") != styles.index("victorian"):
        return False
    if music.index("rock") != styles.index("colonial"):
        return False
    if styles.index("craftsman") != names.index("Carol"):
        return False
    if pets[5] != "rabbit":
        return False
    if not music.index("pop") < styles.index("colonial"):
        return False
    if abs(phones.index("huawei p50") - music.index("country")) != 1:
        return False
    if music.index("hip hop") != phones.index("samsung galaxy s21"):
        return False
    if abs(names.index("Carol") - names.index("Peter")) != 1:
        return False
    if phones.index("oneplus 9") != names.index("Peter"):
        return False
    if pets.index("hamster") == 0:
        return False
    if not styles.index("ranch") < music.index("classical"):
        return False
    if abs(names.index("Carol") - names.index("Alice")) != 3:
        return False
    if pets[4] != "dog":
        return False
    if styles.index("modern") != names.index("Eric"):
        return False
    if names.index("Peter") != styles.index("colonial"):
        return False
    if pets.index("cat") == 3:
        return False
    return True


def main():
    for names in itertools.permutations(NAMES):
        if not names_ok(names):
            continue
        for styles in itertools.permutations(STYLES):
            if not styles_ok(styles, names):
                continue
            for music in itertools.permutations(MUSIC):
                if not music_ok(music, styles):
                    continue
                for phones in itertools.permutations(PHONES):
                    if not phones_ok(phones, names, styles, music):
                        continue
                    for pets in itertools.permutations(PETS):
                        if pets_ok(pets, styles, phones) and valid_solution(names, styles, music, phones, pets):
                            for house in range(6):
                                print(
                                    f"House {house + 1}: "
                                    f"{names[house]}, {music[house]}, {styles[house]}, "
                                    f"{phones[house]}, {pets[house]}"
                                )
                            return


if __name__ == "__main__":
