from itertools import permutations

names = [
    "Alice", "Eric", "Bob", "Peter", "Arnold", "Carol"
]
heights = [
    "very tall", "tall", "super tall", "average", "very short", "short"
]
phones = [
    "oneplus 9", "google pixel 6", "samsung galaxy s21",
    "iphone 13", "huawei p50", "xiaomi mi 11"
]

for h in permutations(heights):
    if h[0] != "super tall":
        continue
    if h[5] != "short":
        continue

    tall_pos = h.index("tall")
    very_tall_pos = h.index("very tall")

    if tall_pos == 0:
        continue

    for n in permutations(names):
        if n[very_tall_pos] != "Carol":
            continue
        if n[tall_pos] != "Arnold":
            continue
        if n[tall_pos - 1] != "Bob":
            continue

        carol_pos = very_tall_pos
        eric_pos = n.index("Eric")
        peter_pos = n.index("Peter")

        for p in permutations(phones):
            if p[carol_pos] != "xiaomi mi 11":
                continue
            if p[0] == "samsung galaxy s21":
                continue

            pixel_pos = p.index("google pixel 6")
            short_pos = h.index("short")

            if abs(pixel_pos - short_pos) != 2:
                continue
            if p[short_pos - 1] != "oneplus 9":
                continue
            if pixel_pos <= eric_pos:
                continue

            iphone_pos = p.index("iphone 13")
            if peter_pos >= iphone_pos:
                continue

            very_short_pos = h.index("very short")
            if very_short_pos <= pixel_pos:
                continue

            for i in range(6):
                print(f"House {i + 1}: {n[i]}, {h[i]}, {p[i]}")
            raise SystemExit

import itertools

NAMES = ["Peter", "Eric", "Arnold", "Alice", "Bob"]
PHONES = ["google pixel 6", "samsung galaxy s21", "huawei p50", "oneplus 9", "iphone 13"]


def satisfies(name_pos, phone_pos):
    return (
        name_pos["Eric"] == phone_pos["samsung galaxy s21"]
        and name_pos["Alice"] == 4
        and phone_pos["samsung galaxy s21"] < phone_pos["google pixel 6"]
        and phone_pos["oneplus 9"] == name_pos["Arnold"] + 1
        and name_pos["Bob"] == phone_pos["huawei p50"]
        and phone_pos["oneplus 9"] == phone_pos["iphone 13"] + 1
        and phone_pos["huawei p50"] == 0
        and phone_pos["google pixel 6"] < phone_pos["oneplus 9"]
    )


solution = None

for name_assign in itertools.permutations(NAMES):
    name_pos = {name: i for i, name in enumerate(name_assign)}

    if name_pos["Alice"] != 4:
        continue

    for phone_assign in itertools.permutations(PHONES):
        phone_pos = {phone: i for i, phone in enumerate(phone_assign)}

        if satisfies(name_pos, phone_pos):
            solution = (name_assign, phone_assign)
            break

    if solution is not None:
        break

if solution is not None:
    name_assign, phone_assign = solution
    for i in range(5):
        print(f"House {i + 1}: {name_assign[i]}, {phone_assign[i]}")

def main():
    houses = [0, 1]
    categories = ["name", "phone", "drink", "sport"]

    domains = {
        "name": ["Eric", "Arnold"],
        "phone": ["iphone 13", "samsung galaxy s21"],
        "drink": ["water", "tea"],
        "sport": ["basketball", "soccer"],
    }

    variables = [(h, cat) for h in houses for cat in categories]

    def consistent(assign):
        for cat in categories:
            seen = set()
            for h in houses:
                value = assign.get((h, cat))
                if value is None:
                    continue
                if value in seen:
                    return False
                seen.add(value)

        for h in houses:
            name = assign.get((h, "name"))
            phone = assign.get((h, "phone"))
            drink = assign.get((h, "drink"))
            sport = assign.get((h, "sport"))

            if name is not None:
                if name == "Arnold" and h != 1:
                    return False
                if h == 1 and name != "Arnold":
                    return False

            if phone is not None and h == 0 and phone == "samsung galaxy s21":
                return False

            if name is not None and sport is not None:
                if (name == "Eric") != (sport == "soccer"):
                    return False

            if phone is not None and drink is not None:
                if (phone == "samsung galaxy s21") != (drink == "tea"):
                    return False

        return True

    def solve(assign, idx):
        if idx == len(variables):
            return True

        h, cat = variables[idx]
        for value in domains[cat]:
            assign[(h, cat)] = value
            if consistent(assign) and solve(assign, idx + 1):
                return True
            del assign[(h, cat)]

        return False

    assignment = {}
    if solve(assignment, 0):
        for h in houses:
            print(
                f"House {h + 1}: "
                f"{assignment[(h, 'name')]}, "
                f"{assignment[(h, 'phone')]}, "
                f"{assignment[(h, 'drink')]}, "
                f"{assignment[(h, 'sport')]}"
            )

if __name__ == "__main__":
    main()

import itertools

NAMES = ["Carol", "Peter", "Arnold", "Alice", "Bob", "Eric"]
