PETS = ["dog", "hamster", "rabbit", "cat", "fish", "bird"]

name_perms = [
    p for p in itertools.permutations(NAMES)
    if p[2] == "Carol" and p[4] == "Arnold"
]

occ_perms = [
    p for p in itertools.permutations(OCCUPATIONS)
    if p[1] == "teacher" and abs(p.index("doctor") - p.index("teacher")) == 1
]

pet_perms = [
    p for p in itertools.permutations(PETS)
    if p[2] == "rabbit"
    and p[3] != "hamster"
    and p[3] != "fish"
    and p[1] != "fish"
]

for names in name_perms:
    name_pos = {name: i for i, name in enumerate(names)}

    for pets in pet_perms:
        pet_pos = {pet: i for i, pet in enumerate(pets)}

        if pet_pos["fish"] != name_pos["Bob"]:
            continue
        if pet_pos["dog"] != name_pos["Peter"]:
            continue
        if not (name_pos["Alice"] < pet_pos["cat"]):
            continue
        if not (pet_pos["hamster"] < name_pos["Eric"]):
            continue

        for occs in occ_perms:
            occ_pos = {occ: i for i, occ in enumerate(occs)}

            if occ_pos["nurse"] != name_pos["Eric"]:
                continue
            if occ_pos["lawyer"] != pet_pos["hamster"]:
                continue
            if pet_pos["dog"] + 1 != occ_pos["artist"]:
                continue

            for house in range(1, 7):
                print(f"House {house}: {names[house - 1]}, {occs[house - 1]}, {pets[house - 1]}")
            raise SystemExit

import sys
from collections import deque

H = 6
cats = ['name', 'vacation', 'pet', 'nat', 'book', 'car']
values = {
    'name': ['Bob', 'Carol', 'Eric', 'Alice', 'Peter', 'Arnold'],
    'vacation': ['camping', 'cruise', 'mountain', 'cultural', 'city', 'beach'],
    'pet': ['fish', 'hamster', 'bird', 'rabbit', 'dog', 'cat'],
    'nat': ['brit', 'swede', 'german', 'norwegian', 'dane', 'chinese'],
    'book': ['biography', 'romance', 'mystery', 'fantasy', 'science fiction', 'historical fiction'],
    'car': ['tesla model 3', 'bmw 3 series', 'honda civic', 'chevrolet silverado', 'toyota camry', 'ford f150']
}

domains = {(c, v): set(range(H)) for c in cats for v in values[c]}

def fix(var, h):
    if h in domains[var]:
        domains[var] = {h}
    else:
        domains[var] = set()

def not_fix(var, h):
    domains[var].discard(h)

