def eq(a, b):
    return a == b

def ne(a, b):
    return a != b

def lt(a, b):
    return a < b

def gt(a, b):
    return a > b

def left(a, b):
    return a + 1 == b

def right(a, b):
    return a - 1 == b

def dist2(a, b):
    return abs(a - b) == 2

def diff2(a, b):
    return a + 2 == b

def diff2_rev(a, b):
    return a - 2 == b

arcs = []
for x, y, typ in constraints:
    if typ == 'eq':
        arcs.append((x, y, eq))
        arcs.append((y, x, eq))
    elif typ == 'ne':
        arcs.append((x, y, ne))
        arcs.append((y, x, ne))
    elif typ == 'lt':
        arcs.append((x, y, lt))
        arcs.append((y, x, gt))
    elif typ == 'gt':
        arcs.append((x, y, gt))
        arcs.append((y, x, lt))
    elif typ == 'left':
        arcs.append((x, y, left))
        arcs.append((y, x, right))
    elif typ == 'dist2':
        arcs.append((x, y, dist2))
        arcs.append((y, x, dist2))
    elif typ == 'diff2':
        arcs.append((x, y, diff2))
        arcs.append((y, x, diff2_rev))

arcs_in = {var: [] for var in domains}
for x, y, rel in arcs:
    arcs_in[y].append((x, y, rel))

degree = {var: len(arcs_in[var]) for var in domains}

def revise(x, y, rel, doms):
    dx = doms[x]
    dy = doms[y]
    if not dx or not dy:
        return False

    new_dx = set()
    for a in dx:
        for b in dy:
            if rel(a, b):
                new_dx.add(a)
                break

    if len(new_dx) != len(dx):
        doms[x] = new_dx
        return True
    return False

def ac3(doms):
    queue = deque(arcs)
    while queue:
        x, y, rel = queue.popleft()
        if not doms[x] or not doms[y]:
            return False
        if revise(x, y, rel, doms):
            if not doms[x]:
                return False
            for z, x2, rel2 in arcs_in[x]:
                queue.append((z, x2, rel2))
    return True

initial = {var: set(d) for var, d in domains.items()}
if not ac3(initial):
    sys.exit(1)

def search(doms):
    best = None
    best_len = H + 1
    best_deg = -1

    for var, d in doms.items():
        if len(d) > 1:
            deg = degree.get(var, 0)
            if len(d) < best_len or (len(d) == best_len and deg > best_deg):
                best = var
                best_len = len(d)
                best_deg = deg

    if best is None:
        for x, y, rel in arcs:
            if not rel(next(iter(doms[x])), next(iter(doms[y]))):
                return None
        return doms

    for val in sorted(doms[best]):
        new_doms = {k: set(v) for k, v in doms.items()}
        new_doms[best] = {val}
        if ac3(new_doms):
            result = search(new_doms)
            if result is not None:
                return result

    return None

sol = search(initial)
if sol is None:
