def main():
    names = ["Arnold", "Peter", "Bob", "Eric", "Carol", "Alice"]
    animals = ["horse", "rabbit", "fish", "cat", "bird", "dog"]
    occupations = ["engineer", "nurse", "lawyer", "teacher", "artist", "doctor"]
    sports = ["basketball", "volleyball", "soccer", "tennis", "baseball", "swimming"]
    heights = ["average", "tall", "short", "very short", "very tall", "super tall"]

    groups = [names, animals, occupations, sports, heights]
    all_values = []
    for g in groups:
        all_values.extend(g)

    domains = {v: set(range(1, 7)) for v in all_values}

    constraints = [
        ("fixed", "lawyer", 5),
        ("fixed", "baseball", 1),
        ("fixed", "super tall", 5),
        ("eq", "engineer", "dog"),
        ("lt", "average", "short"),
        ("left", "average", "rabbit"),
        ("lt", "tall", "very short"),
        ("eq", "Arnold", "cat"),
        ("eq", "horse", "teacher"),
        ("eq", "Carol", "soccer"),
        ("eq", "tall", "volleyball"),
        ("eq", "tennis", "teacher"),
        ("eq", "average", "swimming"),
        ("left", "baseball", "engineer"),
        ("eq", "Peter", "nurse"),
        ("lt", "artist", "Bob"),
        ("left", "teacher", "soccer"),
        ("eq", "rabbit", "Alice"),
        ("eq", "fish", "Carol"),
        ("lt", "very short", "cat"),
    ]

    degree = {v: 0 for v in all_values}
    for c in constraints:
        if c[0] == "fixed":
            degree[c[1]] += 1
        else:
            degree[c[1]] += 1
            degree[c[2]] += 1

    def enforce_all_diff(d, group):
        changed = False
        assigned = {}

        for v in group:
            if len(d[v]) == 1:
                val = next(iter(d[v]))
                if val in assigned:
                    return False, False
                assigned[val] = v

        for v in group:
            if len(d[v]) != 1:
                new = d[v] - set(assigned.keys())
                if not new:
                    return False, False
                if new != d[v]:
                    d[v] = new
                    changed = True

        for pos in range(1, 7):
            candidates = [v for v in group if pos in d[v]]
            if len(candidates) == 1:
                v = candidates[0]
                if len(d[v]) != 1:
                    d[v] = {pos}
                    changed = True

        return True, changed

    def enforce_fixed(d, var, val):
        if val not in d[var]:
            return False, False
        if len(d[var]) != 1:
            d[var] = {val}
            return True, True
        return True, False

    def enforce_eq(d, a, b):
        inter = d[a] & d[b]
        if not inter:
            return False, False

        changed = False
        if d[a] != inter:
            d[a] = inter
            changed = True
        if d[b] != inter:
            d[b] = inter
            changed = True

        return True, changed

    def enforce_lt(d, a, b):
        new_a = {x for x in d[a] if any(y > x for y in d[b])}
        if not new_a:
            return False, False

        changed = False
        if new_a != d[a]:
            d[a] = new_a
            changed = True

        new_b = {y for y in d[b] if any(x < y for x in d[a])}
        if not new_b:
            return False, False

        if new_b != d[b]:
            d[b] = new_b
            changed = True

        return True, changed

    def enforce_left(d, a, b):
        new_a = {x for x in d[a] if x + 1 in d[b]}
        if not new_a:
            return False, False

        changed = False
        if new_a != d[a]:
            d[a] = new_a
            changed = True

        new_b = {y for y in d[b] if y - 1 in d[a]}
        if not new_b:
            return False, False

        if new_b != d[b]:
            d[b] = new_b
            changed = True

        return True, changed

    def propagate(d):
        changed = True
        while changed:
            changed = False

            for group in groups:
                ok, ch = enforce_all_diff(d, group)
                if not ok:
                    return False
                changed = changed or ch

            for c in constraints:
                if c[0] == "fixed":
                    ok, ch = enforce_fixed(d, c[1], c[2])
                elif c[0] == "eq":
                    ok, ch = enforce_eq(d, c[1], c[2])
                elif c[0] == "lt":
                    ok, ch = enforce_lt(d, c[1], c[2])
                else:
                    ok, ch = enforce_left(d, c[1], c[2])

                if not ok:
                    return False
                changed = changed or ch

        return True

    def select_variable(d):
        candidates = [v for v in all_values if len(d[v]) > 1]
        if not candidates:
            return None
        return min(candidates, key=lambda v: (len(d[v]), -degree[v], v))

    def solve(d):
        if not propagate(d):
            return None

        var = select_variable(d)
        if var is None:
            return d

        for val in sorted(d[var]):
            nd = {k: set(v) for k, v in d.items()}
            nd[var] = {val}
            sol = solve(nd)
            if sol is not None:
                return sol

        return None

    solution = solve(domains)
    if solution is None:
        return

    def value_in(group, house):
        for v in group:
            if next(iter(solution[v])) == house:
                return v
        return ""

    for house in range(1, 7):
        print(
            f"House {house}: "
            f"{value_in(names, house)}, "
            f"{value_in(animals, house)}, "
            f"{value_in(occupations, house)}, "
            f"{value_in(sports, house)}, "
            f"{value_in(heights, house)}"
        )


if __name__ == "__main__":
    main()

