]


def check(assigned):
    for c1, v1, c2, v2 in equalities:
        if c1 in assigned and c2 in assigned:
            if assigned[c1].index(v1) != assigned[c2].index(v2):
                return False

    for c1, v1, c2, v2 in direct_left:
        if c1 in assigned and c2 in assigned:
            if assigned[c1].index(v1) + 1 != assigned[c2].index(v2):
                return False

    for c1, v1, c2, v2 in right_of:
        if c1 in assigned and c2 in assigned:
            if assigned[c1].index(v1) <= assigned[c2].index(v2):
                return False

    for c, v, house in not_house:
        if c in assigned:
            if assigned[c].index(v) == house:
                return False

    return True


