def backtrack(depth):
    if depth == len(order):
        return True

    category = order[depth]
    for perm in itertools.permutations(values[category]):
        assignment[category] = perm
        if check(assignment):
            if backtrack(depth + 1):
                return True

    del assignment[category]
    return False


