import sys

names = ["Eric", "Peter", "Alice", "Arnold"]
hairs = ["brown", "black", "blonde", "red"]
sports = ["tennis", "basketball", "soccer", "swimming"]
smoothies = ["watermelon", "cherry", "dragonfruit", "desert"]
birthdays = ["april", "sept", "feb", "jan"]
phones = ["oneplus 9", "samsung galaxy s21", "iphone 13", "google pixel 6"]

categories = [names, hairs, sports, smoothies, birthdays, phones]
all_vars = [v for cat in categories for v in cat]

domains = {v: {0, 1, 2, 3} for v in all_vars}
domains["dragonfruit"] = {1}

equality_pairs = [
    ("Eric", "oneplus 9"),
    ("Arnold", "april"),
    ("black", "feb"),
    ("black", "samsung galaxy s21"),
    ("Alice", "cherry"),
    ("desert", "google pixel 6"),
]

rel_constraints = [
    ("lt", "jan", "basketball", None),
    ("direct_left", "feb", "red", None),
    ("next", "samsung galaxy s21", "cherry", None),
    ("next", "blonde", "Peter", None),
    ("gt", "black", "brown", None),
    ("gt", "soccer", "oneplus 9", None),
    ("diff", "tennis", "basketball", 3),
]

def relation_holds(rel, x, y, param=None):
    if rel == "lt":
        return x < y
    if rel == "gt":
        return x > y
    if rel == "direct_left":
        return x + 1 == y
    if rel == "next":
        return abs(x - y) == 1
    if rel == "diff":
        return abs(x - y) == param
    return False

degree = {v: 0 for v in all_vars}
for a, b in equality_pairs:
    degree[a] += 1
    degree[b] += 1
for _, a, b, _ in rel_constraints:
    degree[a] += 1
    degree[b] += 1
for cat in categories:
    for v in cat:
        degree[v] += len(cat)

def propagate(dom):
    while True:
        for d in dom.values():
            if not d:
                return False

        changed = False

        for a, b in equality_pairs:
            inter = dom[a] & dom[b]
            if not inter:
                return False
            if inter != dom[a]:
                dom[a] = inter
                changed = True
            if inter != dom[b]:
                dom[b] = inter
                changed = True

        for rel, a, b, param in rel_constraints:
            da = dom[a]
            db = dom[b]
            if not da or not db:
                return False

            new_da = {x for x in da if any(relation_holds(rel, x, y, param) for y in db)}
            if new_da != da:
                dom[a] = new_da
                changed = True
                if not new_da:
                    return False
                da = new_da

            new_db = {y for y in db if any(relation_holds(rel, x, y, param) for x in da)}
            if new_db != db:
                dom[b] = new_db
                changed = True
                if not new_db:
                    return False

        for cat in categories:
            assigned = {}
            for v in cat:
                if len(dom[v]) == 1:
                    val = next(iter(dom[v]))
                    if val in assigned:
                        return False
                    assigned[val] = v

            for val, owner in assigned.items():
                for v in cat:
                    if v != owner and val in dom[v]:
                        dom[v] = dom[v] - {val}
                        changed = True
                        if not dom[v]:
                            return False

        if not changed:
            return True

def check_solution(dom):
    for cat in categories:
        vals = [next(iter(dom[v])) for v in cat]
        if len(set(vals)) != 4:
            return False

    for a, b in equality_pairs:
        if next(iter(dom[a])) != next(iter(dom[b])):
            return False

    for rel, a, b, param in rel_constraints:
        if not relation_holds(rel, next(iter(dom[a])), next(iter(dom[b])), param):
            return False

    if next(iter(dom["dragonfruit"])) != 1:
        return False

    return True

def solve(dom):
    if not propagate(dom):
        return None

    unassigned = [v for v in all_vars if len(dom[v]) > 1]
    if not unassigned:
        if check_solution(dom):
            return {v: next(iter(dom[v])) for v in all_vars}
        return None

    var = min(unassigned, key=lambda v: (len(dom[v]), -degree[v]))

    for val in sorted(dom[var]):
        new_dom = {k: set(s) for k, s in dom.items()}
        new_dom[var] = {val}
        result = solve(new_dom)
        if result is not None:
            return result

    return None

sol = solve(domains)
if sol is None:
    sys.exit(1)

houses = [[None] * len(categories) for _ in range(4)]
for ci, cat in enumerate(categories):
    for v in cat:
        houses[sol[v]][ci] = v

for i in range(4):
    print(f"House {i + 1}: {', '.join(houses[i])}")

