    if abs(lunch_pos['spaghetti'] - edu_pos['associate']) != 3:
        return False
    if cigar_pos['prince'] == 2:
        return False
    if abs(cigar_pos['dunhill'] - name_pos['Bob']) != 1:
        return False
    if abs(name_pos['Alice'] - drink_pos['boba tea']) != 3:
        return False
    if edu_pos['high school'] != name_pos['Eric']:
        return False
    if edu_pos['trade school'] != cigar_pos['prince']:
        return False
    if abs(cigar_pos['dunhill'] - lunch_pos['stir fry']) != 2:
        return False
    if cigar_pos['dunhill'] + 1 != lunch_pos['pizza']:
        return False
    if abs(cigar_pos['pall mall'] - cigar_pos['blue master']) != 2:
        return False
    if cigar_pos['blue master'] != drink_pos['coffee']:
        return False
    if edu_pos['bachelor'] != cigar_pos['dunhill']:
        return False
    if name_pos['Alice'] != drink_pos['tea']:
        return False
    if name_pos['Arnold'] + 1 != drink_pos['root beer']:
        return False
    if edu_pos['master'] != name_pos['Peter']:
        return False
    if not name_pos['Arnold'] < drink_pos['milk']:
        return False
    return True


def build_solution(name_pos, lunch_pos, cigar_pos, drink_pos, edu_pos):
    name_at = [None] * 6
    lunch_at = [None] * 6
    cigar_at = [None] * 6
    drink_at = [None] * 6
    edu_at = [None] * 6

    for value, pos in name_pos.items():
        name_at[pos] = value
    for value, pos in lunch_pos.items():
        lunch_at[pos] = value
    for value, pos in cigar_pos.items():
        cigar_at[pos] = value
    for value, pos in drink_pos.items():
        drink_at[pos] = value
    for value, pos in edu_pos.items():
        edu_at[pos] = value

    return '\n'.join(
        f"House {i + 1}: {name_at[i]}, {lunch_at[i]}, {cigar_at[i]}, {drink_at[i]}, {edu_at[i]}"
        for i in range(6)
    )


def solve():
    for name_perm in permutations(NAMES):
        name_pos = dict(zip(name_perm, range(6)))
        if name_pos['Bob'] == 1:
            continue

        bob_pos = name_pos['Bob']
        eric_pos = name_pos['Eric']
        blue_pos = eric_pos

        for dunhill_pos in (bob_pos - 1, bob_pos + 1):
            if not (0 <= dunhill_pos < 6):
                continue
            if dunhill_pos == blue_pos:
                continue

            for pall_mall_pos in range(dunhill_pos + 1, 6):
                if pall_mall_pos == blue_pos:
                    continue
                if abs(pall_mall_pos - blue_pos) != 2:
                    continue

                used_cigar_pos = {blue_pos, dunhill_pos, pall_mall_pos}

                for prince_pos in range(6):
                    if prince_pos in used_cigar_pos or prince_pos == 2:
                        continue

                    remaining_cigar_pos = [
                        i for i in range(6)
                        if i not in used_cigar_pos and i != prince_pos
                    ]

                    for blends_pos, yellow_pos in (
                        (remaining_cigar_pos[0], remaining_cigar_pos[1]),
                        (remaining_cigar_pos[1], remaining_cigar_pos[0]),
                    ):
                        cigar_pos = {
                            'blue master': blue_pos,
                            'dunhill': dunhill_pos,
                            'pall mall': pall_mall_pos,
                            'prince': prince_pos,
                            'blends': blends_pos,
                            'yellow monster': yellow_pos,
                        }

                        fixed_edu_pos = {
                            'high school': eric_pos,
                            'master': name_pos['Peter'],
                            'bachelor': dunhill_pos,
                            'trade school': prince_pos,
                        }

                        if len(set(fixed_edu_pos.values())) != 4:
                            continue

                        used_edu_pos = set(fixed_edu_pos.values())
                        remaining_edu_pos = [i for i in range(6) if i not in used_edu_pos]

                        for associate_pos, doctorate_pos in (
                            (remaining_edu_pos[0], remaining_edu_pos[1]),
                            (remaining_edu_pos[1], remaining_edu_pos[0]),
                        ):
                            edu_pos = dict(fixed_edu_pos)
                            edu_pos['associate'] = associate_pos
                            edu_pos['doctorate'] = doctorate_pos

                            alice_pos = name_pos['Alice']
                            arnold_pos = name_pos['Arnold']
                            root_beer_pos = arnold_pos + 1

                            if root_beer_pos >= 6:
                                continue

                            fixed_drink_pos = {
                                'coffee': eric_pos,
                                'tea': alice_pos,
                                'root beer': root_beer_pos,
                            }

                            if len(set(fixed_drink_pos.values())) != 3:
                                continue

                            used_drink_pos = set(fixed_drink_pos.values())
                            remaining_drink_pos = [i for i in range(6) if i not in used_drink_pos]

                            for drink_perm in DRINK_REMAINING_PERMS:
                                drink_pos = dict(fixed_drink_pos)
                                for value, pos in zip(drink_perm, remaining_drink_pos):
                                    drink_pos[value] = pos

                                if abs(drink_pos['boba tea'] - alice_pos) != 3:
                                    continue
                                if not arnold_pos < drink_pos['milk']:
                                    continue
                                if drink_pos['milk'] >= 5:
                                    continue

                                d = dunhill_pos
                                a = associate_pos
                                soup_pos = doctorate_pos

                                if soup_pos == 0:
                                    continue

                                pizza_pos = d + 1
                                if pizza_pos >= 6:
                                    continue

                                stew_pos = drink_pos['milk'] + 1
                                if stew_pos >= 6:
                                    continue

                                if not cigar_pos['blends'] < pizza_pos:
                                    continue

                                fixed_lunch_pos = {
                                    'soup': soup_pos,
                                    'pizza': pizza_pos,
                                    'stew': stew_pos,
                                }

                                if len(set(fixed_lunch_pos.values())) != 3:
                                    continue

                                used_lunch_pos = set(fixed_lunch_pos.values())

                                stir_candidates = [
                                    x for x in (d - 2, d + 2)
                                    if 0 <= x < 6 and x not in used_lunch_pos
                                ]
                                spag_candidates = [
                                    x for x in (a - 3, a + 3)
                                    if 0 <= x < 6 and x not in used_lunch_pos
                                ]

                                for stir_pos in stir_candidates:
                                    for spag_pos in spag_candidates:
                                        if spag_pos == stir_pos:
                                            continue
                                        if spag_pos in used_lunch_pos or stir_pos in used_lunch_pos:
                                            continue

                                        all_used_lunch_pos = used_lunch_pos | {stir_pos, spag_pos}
                                        if len(all_used_lunch_pos) != 5:
                                            continue

                                        grilled_pos = next(
                                            i for i in range(6)
                                            if i not in all_used_lunch_pos
                                        )

                                        lunch_pos = {
                                            'soup': soup_pos,
                                            'pizza': pizza_pos,
                                            'stew': stew_pos,
                                            'stir fry': stir_pos,
                                            'spaghetti': spag_pos,
                                            'grilled cheese': grilled_pos,
                                        }

                                        if satisfies(name_pos, lunch_pos, cigar_pos, drink_pos, edu_pos):
                                            return build_solution(
                                                name_pos, lunch_pos, cigar_pos, drink_pos, edu_pos
                                            )

    return None


if __name__ == '__main__':
    solution = solve()
    if solution is not None:
        print(solution)

import sys
from collections import deque

sys.setrecursionlimit(10000)


def main():
    categories = ["name", "lunch", "color", "mother", "style"]
    values = {
        "name": ["Carol", "Eric", "Peter", "Alice", "Bob", "Arnold"],
        "lunch": ["spaghetti", "soup", "grilled cheese", "stir fry", "stew", "pizza"],
        "color": ["green", "purple", "blue", "red", "white", "yellow"],
        "mother": ["Holly", "Penny", "Aniya", "Kailyn", "Sarah", "Janelle"],
        "style": ["colonial", "craftsman", "modern", "ranch", "victorian", "mediterranean"],
    }

    var_list = [(cat, val) for cat in categories for val in values[cat]]

    domains = {v: set(range(1, 7)) for v in var_list}
    domains[("name", "Carol")] = {1, 2, 3, 4, 5}
    domains[("lunch", "spaghetti")] = {1, 2, 3, 4, 6}

    constraints = []
    arcs = []

    def add_constraint(a, b, pred):
        constraints.append((a, b, pred))
        arcs.append((a, b, pred))
        arcs.append((b, a, lambda x, y, p=pred: p(y, x)))

    for cat in categories:
        vals = values[cat]
        for i in range(len(vals)):
            for j in range(i + 1, len(vals)):
                add_constraint((cat, vals[i]), (cat, vals[j]), lambda x, y: x != y)

    add_constraint(("mother", "Janelle"), ("style", "colonial"), lambda x, y: x == y)
    add_constraint(("name", "Peter"), ("color", "green"), lambda x, y: x == y)
    add_constraint(("color", "blue"), ("lunch", "spaghetti"), lambda x, y: x + 1 == y)
    add_constraint(("mother", "Penny"), ("color", "red"), lambda x, y: x + 1 == y)
    add_constraint(("color", "blue"), ("mother", "Penny"), lambda x, y: x == y)
    add_constraint(("mother", "Aniya"), ("color", "green"), lambda x, y: x + 1 == y)
    add_constraint(("color", "white"), ("mother", "Janelle"), lambda x, y: x < y)
    add_constraint(("name", "Eric"), ("lunch", "grilled cheese"), lambda x, y: x == y)
    add_constraint(("mother", "Holly"), ("name", "Alice"), lambda x, y: x + 1 == y)
    add_constraint(("mother", "Holly"), ("lunch", "stew"), lambda x, y: abs(x - y) == 1)
    add_constraint(("name", "Alice"), ("style", "ranch"), lambda x, y: x == y)
    add_constraint(("lunch", "stir fry"), ("color", "purple"), lambda x, y: x == y)
    add_constraint(("color", "red"), ("style", "colonial"), lambda x, y: abs(x - y) == 1)
    add_constraint(("lunch", "soup"), ("name", "Peter"), lambda x, y: x == y)
    add_constraint(("lunch", "pizza"), ("mother", "Sarah"), lambda x, y: x < y)
    add_constraint(("style", "victorian"), ("lunch", "grilled cheese"), lambda x, y: x == y)
    add_constraint(("lunch", "grilled cheese"), ("mother", "Aniya"), lambda x, y: abs(x - y) == 3)
    add_constraint(("name", "Arnold"), ("color", "red"), lambda x, y: x == y)
    add_constraint(("style", "modern"), ("name", "Arnold"), lambda x, y: x == y)
    add_constraint(("color", "yellow"), ("style", "mediterranean"), lambda x, y: x == y)

    arcs_in = {v: [] for v in var_list}
    for x, y, pred in arcs:
        arcs_in[y].append((x, pred))
    degree = {v: len(arcs_in[v]) for v in var_list}

    def revise(x, y, pred, dom):
        new_domain = set()
        for xv in dom[x]:
            for yv in dom[y]:
                if pred(xv, yv):
                    new_domain.add(xv)
                    break
        if len(new_domain) != len(dom[x]):
            dom[x] = new_domain
            return True
        return False

    def ac3(dom):
        queue = deque(arcs)
        while queue:
            x, y, pred = queue.popleft()
            if revise(x, y, pred, dom):
                if not dom[x]:
                    return False
                for z, pred_zx in arcs_in[x]:
                    if z != y:
                        queue.append((z, x, pred_zx))
        return True

    if not ac3(domains):
        return

    def search(dom):
        for v in var_list:
            if not dom[v]:
                return None

        if all(len(dom[v]) == 1 for v in var_list):
            return {v: next(iter(dom[v])) for v in var_list}

        var = min(
            var_list,
            key=lambda v: (len(dom[v]) == 1, len(dom[v]), -degree[v]),
        )

        for val in sorted(dom[var]):
            new_dom = {v: set(s) for v, s in dom.items()}
            new_dom[var] = {val}
            if ac3(new_dom):
                result = search(new_dom)
                if result is not None:
                    return result
        return None

    solution = search(domains)
    if solution is None:
        return

    for a, b, pred in constraints:
        if not pred(solution[a], solution[b]):
            return

    house_attrs = {h: {} for h in range(1, 7)}
    for (cat, val), house in solution.items():
        house_attrs[house][cat] = val

    order = ["name", "lunch", "color", "mother", "style"]
    out_lines = []
    for h in range(1, 7):
        attrs = [house_attrs[h][cat] for cat in order]
        out_lines.append(f"House {h}: " + ", ".join(attrs))

    sys.stdout.write("\n".join(out_lines))


if __name__ == "__main__":
    main()

