N = 5

CATEGORIES = {
    'name': ['Alice', 'Arnold', 'Eric', 'Bob', 'Peter'],
    'drink': ['root beer', 'water', 'coffee', 'tea', 'milk'],
    'month': ['jan', 'april', 'sept', 'feb', 'mar'],
    'occ': ['teacher', 'lawyer', 'engineer', 'doctor', 'artist'],
    'vac': ['city', 'cruise', 'mountain', 'beach', 'camping'],
}


def remove_value(domains, var, val):
    if val in domains[var]:
        domains[var].discard(val)
        if not domains[var]:
            return False
    return True


def make_unary(var, forbidden):
    def f(domains):
        if forbidden in domains[var]:
            domains[var].discard(forbidden)
            if not domains[var]:
                return False
        return True
    return f


def make_alldiff(cat):
    vars = [(cat, h) for h in range(N)]
    values = CATEGORIES[cat]

    def f(domains):
        for v in values:
            holders = [var for var in vars if v in domains[var]]
            if not holders:
                return False

            singletons = [var for var in holders if len(domains[var]) == 1]
            if len(singletons) > 1:
                return False

            if singletons:
                for var in holders:
                    if var not in singletons and v in domains[var]:
                        if not remove_value(domains, var, v):
                            return False
        return True
    return f


def make_iff(var1, val1, var2, val2):
    def f(domains):
        d1 = domains[var1]
        d2 = domains[var2]
        if not d1 or not d2:
            return False

        has_non_val2 = any(b != val2 for b in d2)
        has_non_val1 = any(a != val1 for a in d1)

        new_d1 = set()
        for a in d1:
            if a == val1:
                if val2 in d2:
                    new_d1.add(a)
            else:
                if has_non_val2:
                    new_d1.add(a)

        new_d2 = set()
        for b in d2:
            if b == val2:
                if val1 in d1:
                    new_d2.add(b)
            else:
                if has_non_val1:
                    new_d2.add(b)

        if not new_d1 or not new_d2:
            return False

        domains[var1] = new_d1
        domains[var2] = new_d2
        return True
    return f


def make_left(cat1, val1, cat2, val2):
    def f(domains):
        p1 = [h for h in range(N) if val1 in domains[(cat1, h)]]
        p2 = [h for h in range(N) if val2 in domains[(cat2, h)]]
        if not p1 or not p2:
            return False

        new_p1 = set()
        for h1 in p1:
            if any(h2 > h1 for h2 in p2):
                new_p1.add(h1)

        new_p2 = set()
        for h2 in p2:
            if any(h1 < h2 for h1 in p1):
                new_p2.add(h2)

        for h in range(N):
            if h not in new_p1:
                if not remove_value(domains, (cat1, h), val1):
                    return False
            if h not in new_p2:
                if not remove_value(domains, (cat2, h), val2):
                    return False
        return True
    return f


def make_direct_left(cat1, val1, cat2, val2):
    def f(domains):
        p1 = [h for h in range(N) if val1 in domains[(cat1, h)]]
        p2 = [h for h in range(N) if val2 in domains[(cat2, h)]]
        if not p1 or not p2:
            return False

        new_p1 = set()
        for h1 in p1:
            if h1 + 1 < N and (h1 + 1) in p2:
                new_p1.add(h1)

        new_p2 = set()
        for h2 in p2:
            if h2 - 1 >= 0 and (h2 - 1) in p1:
                new_p2.add(h2)

        for h in range(N):
            if h not in new_p1:
                if not remove_value(domains, (cat1, h), val1):
                    return False
            if h not in new_p2:
                if not remove_value(domains, (cat2, h), val2):
                    return False
        return True
    return f


