def propagate(domains):
    while True:
        for d in domains.values():
            if not d:
                return False

        old = {var: set(vals) for var, vals in domains.items()}
        for func in constraints:
            if not func(domains):
                return False

        if domains == old:
            return True


def validate(domains):
    if any(len(d) != 1 for d in domains.values()):
        return False

    a = {var: next(iter(vals)) for var, vals in domains.items()}

    for cat in CATEGORIES:
        vals = [a[(cat, h)] for h in range(N)]
        if len(set(vals)) != N:
