        if (a[('month', h)] == 'april') != (a[('drink', h)] == 'water'):
            return False
        if (a[('month', h)] == 'jan') != (a[('drink', h)] == 'root beer'):
            return False

    def pos(cat, val):
        for h in range(N):
            if a[(cat, h)] == val:
                return h
        return None

    h = pos('occ', 'doctor')
    k = pos('vac', 'city')
    if h is None or k is None or h + 1 != k:
