    h = pos('drink', 'tea')
    k = pos('vac', 'camping')
    if h is None or k is None or h >= k:
        return False

    h = pos('occ', 'teacher')
    k = pos('occ', 'lawyer')
    if h is None or k is None or h >= k:
        return False

    return True


failed = set()


def state_key(domains):
    return tuple(sorted((var, tuple(sorted(vals))) for var, vals in domains.items()))


def solve(domains):
    if not propagate(domains):
        return None

    key = state_key(domains)
    if key in failed:
        return None

    unassigned = [var for var in domains if len(domains[var]) > 1]
    if not unassigned:
        if validate(domains):
            return domains
        failed.add(key)
        return None

    var = min(unassigned, key=lambda x: len(domains[x]))
    for val in sorted(domains[var]):
        new_domains = {v: set(vals) for v, vals in domains.items()}
        new_domains[var] = {val}
        result = solve(new_domains)
        if result is not None:
            return result

    failed.add(key)
    return None


