            continue

        for color_assignment in permutations(colors):
            color_pos = {color: i + 1 for i, color in enumerate(color_assignment)}

            # Bob is the person who loves white.
            if name_pos["Bob"] != color_pos["white"]:
                continue

            # The person who loves yellow is somewhere to the right of Alice.
            if color_pos["yellow"] <= name_pos["Alice"]:
                continue

            # The person who loves yellow is not in the fourth house.
            if color_pos["yellow"] == 4:
                continue

