import sys

names = ["Alice", "Peter", "Bob", "Eric", "Arnold"]
flowers = ["tulips", "daffodils", "lilies", "roses", "carnations"]
children = ["Fred", "Bella", "Timothy", "Meredith", "Samantha"]
educations = ["high school", "bachelor", "doctorate", "master", "associate"]
animals = ["cat", "fish", "dog", "horse", "bird"]

categories = {
    "name": names,
    "flower": flowers,
    "child": children,
    "education": educations,
    "animal": animals,
}

all_vars = [(cat, value) for cat, values in categories.items() for value in values]
initial_domains = {var: set(range(5)) for var in all_vars}
initial_domains[("child", "Meredith")] = {0, 1, 3, 4}

constraints = [
    (("animal", "dog"), ("name", "Peter"), "lt"),
    (("flower", "carnations"), ("education", "bachelor"), "distance2"),
    (("education", "doctorate"), ("animal", "cat"), "distance2"),
    (("education", "associate"), ("flower", "tulips"), "left"),
    (("animal", "cat"), ("animal", "horse"), "distance2"),
    (("child", "Fred"), ("education", "bachelor"), "lt"),
    (("education", "master"), ("child", "Bella"), "eq"),
    (("education", "bachelor"), ("name", "Bob"), "eq"),
    (("child", "Timothy"), ("flower", "daffodils"), "eq"),
    (("child", "Samantha"), ("name", "Bob"), "eq"),
    (("name", "Arnold"), ("name", "Peter"), "left"),
    (("animal", "bird"), ("flower", "daffodils"), "left"),
    (("flower", "roses"), ("animal", "bird"), "eq"),
    (("animal", "dog"), ("animal", "fish"), "distance2"),
    (("flower", "tulips"), ("name", "Eric"), "eq"),
]

groups = [list((cat, value) for value in values) for cat, values in categories.items()]
degree = {var: 0 for var in all_vars}
for a, b, _ in constraints:
    degree[a] += 1
    degree[b] += 1


def compatible(h1, h2, rel):
    if rel == "eq":
        return h1 == h2
    if rel == "left":
        return h1 + 1 == h2
    if rel == "lt":
        return h1 < h2
    if rel == "distance2":
        return abs(h1 - h2) == 2
    return False


def all_diff_ok(assigned):
    for group in groups:
        seen = set()
        for var in group:
            if var in assigned:
                house = assigned[var]
                if house in seen:
                    return False
                seen.add(house)
    return True


def search(assigned, domains):
    if len(assigned) == len(all_vars):
        for a, b, rel in constraints:
            if not compatible(assigned[a], assigned[b], rel):
                return None
        if not all_diff_ok(assigned):
            return None
        return assigned

    best_var = None
    best_key = None
    for var in all_vars:
        if var in assigned:
            continue
        size = len(domains[var])
        if size == 0:
            return None
        key = (size, -degree[var])
        if best_key is None or key < best_key:
            best_key = key
            best_var = var

    if best_var is None:
        return None

    for house in sorted(domains[best_var]):
        new_assigned = dict(assigned)
        new_assigned[best_var] = house

        ok = all_diff_ok(new_assigned)
        if ok:
            for a, b, rel in constraints:
                if a in new_assigned and b in new_assigned:
                    if not compatible(new_assigned[a], new_assigned[b], rel):
                        ok = False
                        break
        if not ok:
            continue

        new_domains = {var: set(domains[var]) for var in all_vars}

        for group in groups:
            if best_var in group:
                for var in group:
                    if var != best_var and var not in new_assigned:
                        new_domains[var].discard(house)
                        if not new_domains[var]:
                            ok = False
                            break
                if not ok:
                    break
        if not ok:
            continue

        for var in all_vars:
            if var in new_assigned:
                continue
            domain = new_domains[var]
            for a, b, rel in constraints:
                if a == var and b in new_assigned:
                    domain = {h for h in domain if compatible(h, new_assigned[b], rel)}
                elif b == var and a in new_assigned:
                    domain = {h for h in domain if compatible(new_assigned[a], h, rel)}
            new_domains[var] = domain
            if not domain:
                ok = False
                break

        if ok:
            result = search(new_assigned, new_domains)
            if result is not None:
                return result

    return None


solution = search({}, initial_domains)
if solution is None:
    sys.exit(1)

