    assigned_names = [assign[h][0] for h in houses if h in assign]
    assigned_animals = [assign[h][1] for h in houses if h in assign]

    if len(set(assigned_names)) != len(assigned_names):
        return False
    if len(set(assigned_animals)) != len(assigned_animals):
        return False

    if 1 in assign:
        if assign[1][0] == "Eric":
            return False
        if assign[1][1] == "cat":
            return False

    return True

