import sys

def main():
    categories = {
        "name": ["Carol", "Arnold", "Bob", "Alice", "Eric", "Peter"],
        "flower": ["carnations", "tulips", "lilies", "roses", "daffodils", "iris"],
        "book": ["science fiction", "fantasy", "romance", "mystery", "biography", "historical fiction"],
        "phone": ["huawei p50", "oneplus 9", "iphone 13", "xiaomi mi 11", "samsung galaxy s21", "google pixel 6"],
        "hair": ["black", "gray", "red", "auburn", "blonde", "brown"],
        "color": ["yellow", "green", "red", "white", "blue", "purple"],
    }

    all_vars = [(cat, val) for cat, vals in categories.items() for val in vals]
    var_cat = {v: cat for v in all_vars}
    vars_by_cat = {cat: [v for v in all_vars if v[0] == cat] for cat in categories}
    degree = {v: 0 for v in all_vars}
    constraints = []

    def add(v1, v2, pred):
        constraints.append((v1, v2, pred))
        degree[v1] += 1
        degree[v2] += 1

    def V(cat, val):
        return (cat, val)

    add(V("hair", "gray"), V("phone", "iphone 13"), lambda a, b: abs(a - b) == 2)
    add(V("flower", "roses"), V("hair", "blonde"), lambda a, b: a == b)
    add(V("hair", "gray"), V("color", "yellow"), lambda a, b: abs(a - b) == 2)
    add(V("name", "Carol"), V("flower", "daffodils"), lambda a, b: a > b)
    add(V("color", "white"), V("name", "Peter"), lambda a, b: a < b)
    add(V("color", "white"), V("book", "science fiction"), lambda a, b: a < b)
    add(V("name", "Arnold"), V("book", "historical fiction"), lambda a, b: a + 1 == b)
    add(V("phone", "huawei p50"), V("flower", "daffodils"), lambda a, b: a == b)
    add(V("color", "purple"), V("book", "fantasy"), lambda a, b: a < b)
    add(V("name", "Eric"), V("book", "science fiction"), lambda a, b: a == b)
    add(V("flower", "daffodils"), V("hair", "auburn"), lambda a, b: a == b)
    add(V("name", "Alice"), V("color", "green"), lambda a, b: a == b)
    add(V("phone", "samsung galaxy s21"), V("name", "Carol"), lambda a, b: a == b)
    add(V("name", "Eric"), V("hair", "auburn"), lambda a, b: a == b)
    add(V("flower", "roses"), V("hair", "red"), lambda a, b: a < b)
    add(V("book", "historical fiction"), V("flower", "roses"), lambda a, b: a == b)
    add(V("phone", "xiaomi mi 11"), V("color", "white"), lambda a, b: a > b)
    add(V("color", "red"), V("book", "mystery"), lambda a, b: a == b)
    add(V("book", "historical fiction"), V("flower", "tulips"), lambda a, b: abs(a - b) == 1)
    add(V("hair", "brown"), V("phone", "oneplus 9"), lambda a, b: a == b)
    add(V("book", "romance"), V("book", "fantasy"), lambda a, b: a < b)
    add(V("flower", "iris"), V("color", "green"), lambda a, b: a > b)

    domains = {v: set(range(6)) for v in all_vars}
    domains[V("book", "fantasy")] = {1}
    domains[V("flower", "lilies")] = {1}
    domains[V("hair", "black")] = {3}
    domains[V("phone", "xiaomi mi 11")] = {0, 1, 2, 4, 5}

    def assign(assignment, domains, var, val):
        if var in assignment:
            return assignment[var] == val and val in domains[var]
        if val not in domains[var]:
            return False

        assignment[var] = val
        domains[var] = {val}

        cat = var_cat[var]
        for other in vars_by_cat[cat]:
            if other == var:
                continue
            if other in assignment:
                if assignment[other] == val:
                    return False
            elif val in domains[other]:
                domains[other].remove(val)
                if not domains[other]:
                    return False

        for v1, v2, pred in constraints:
            if var not in (v1, v2):
                continue
            other = v2 if v1 == var else v1
            if other in assignment:
                a = assignment[var]
                b = assignment[other]
                ok = pred(a, b) if v1 == var else pred(b, a)
                if not ok:
                    return False
            else:
                newd = set()
                if v1 == var:
                    for x in domains[other]:
                        if pred(val, x):
                            newd.add(x)
                else:
                    for x in domains[other]:
                        if pred(x, val):
                            newd.add(x)
                if not newd:
                    return False
                domains[other] = newd

        return True

    def propagate(assignment, domains):
        while True:
            for v in all_vars:
                if v not in assignment and not domains[v]:
                    return False

            assigned = False
            for v in all_vars:
                if v not in assignment and len(domains[v]) == 1:
                    val = next(iter(domains[v]))
                    if not assign(assignment, domains, v, val):
                        return False
                    assigned = True
                    break
            if assigned:
                continue

            hidden = False
            for cat, vars in vars_by_cat.items():
                for h in range(6):
                    candidates = [v for v in vars if v not in assignment and h in domains[v]]
                    if len(candidates) == 0:
                        if not any(v in assignment and assignment[v] == h for v in vars):
                            return False
                    elif len(candidates) == 1:
                        v = candidates[0]
                        if len(domains[v]) > 1:
                            if not assign(assignment, domains, v, h):
                                return False
                            hidden = True
                            break
                if hidden:
                    break
            if hidden:
                continue

            return True

    def backtrack(assignment, domains):
        if not propagate(assignment, domains):
            return None

        if len(assignment) == len(all_vars):
            for v1, v2, pred in constraints:
                if not pred(assignment[v1], assignment[v2]):
                    return None
            for cat, vars in vars_by_cat.items():
                if len({assignment[v] for v in vars}) != 6:
                    return None
            return assignment

        unassigned = [v for v in all_vars if v not in assignment]
        var = min(unassigned, key=lambda v: (len(domains[v]), -degree[v], v))

        for val in sorted(domains[var]):
            new_assignment = assignment.copy()
            new_domains = {v: set(d) for v, d in domains.items()}
            if assign(new_assignment, new_domains, var, val):
                result = backtrack(new_assignment, new_domains)
                if result is not None:
