    }

    def V(c, v):
        return (c, v)

    all_vars = [(c, v) for c in cats for v in values[c]]
    cat_vars = {c: [V(c, v) for v in values[c]] for c in cats}
    initial_domains = {v: set(range(6)) for v in all_vars}

    unary = []
    binary = []

    def fixed(var, pos):
        unary.append((var, pos, 'eq'))

    def not_fixed(var, pos):
        unary.append((var, pos, 'ne'))

    def same(a, b):
        binary.append((a, b, lambda x, y: x == y))

    def left(a, b):
        binary.append((a, b, lambda x, y: x < y))

    def direct_left(a, b):
        binary.append((a, b, lambda x, y: x == y - 1))

    def adjacent(a, b):
        binary.append((a, b, lambda x, y: abs(x - y) == 1))

    def dist3(a, b):
        binary.append((a, b, lambda x, y: abs(x - y) == 3))

    # Clue 1
