    # Clue 25
    not_fixed(V('cigar', 'blue master'), 4)

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            for v in all_vars:
                if not domains[v]:
                    return None

            for var, const, op in unary:
                dom = domains[var]
                if op == 'eq':
                    if const not in dom:
                        return None
                    if len(dom) != 1:
                        domains[var] = {const}
                        changed = True
                else:
                    if const in dom:
                        new_dom = dom - {const}
                        if not new_dom:
                            return None
                        domains[var] = new_dom
                        changed = True

            for x, y, rel in binary:
                dx = domains[x]
                dy = domains[y]
                if not dx or not dy:
                    return None

                new_dx = set()
                for xv in dx:
                    for yv in dy:
                        if rel(xv, yv):
                            new_dx.add(xv)
                            break
                if new_dx != dx:
                    if not new_dx:
                        return None
                    domains[x] = new_dx
                    dx = new_dx
                    changed = True

                new_dy = set()
                for yv in dy:
                    for xv in dx:
                        if rel(xv, yv):
                            new_dy.add(yv)
                            break
                if new_dy != dy:
                    if not new_dy:
                        return None
                    domains[y] = new_dy
                    changed = True

            for cat in cats:
                vars_cat = cat_vars[cat]

                for h in range(6):
                    supporters = []
                    for v in vars_cat:
                        if h in domains[v]:
                            supporters.append(v)

                    if len(supporters) == 0:
                        return None

                    if len(supporters) == 1:
                        v = supporters[0]
                        if len(domains[v]) != 1:
                            domains[v] = {h}
                            changed = True

                for v in vars_cat:
                    if len(domains[v]) == 1:
                        h = next(iter(domains[v]))
                        for u in vars_cat:
                            if u != v and h in domains[u]:
                                new_dom = domains[u] - {h}
                                if not new_dom:
                                    return None
                                domains[u] = new_dom
                                changed = True

        return domains

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        var = None
        best = 7
        for v in all_vars:
            l = len(domains[v])
            if l == 0:
                return None
            if l > 1 and l < best:
                best = l
                var = v
                if best == 2:
                    break

        if var is None:
            return domains

        for val in sorted(domains[var]):
            new_domains = {k: set(d) for k, d in domains.items()}
            new_domains[var] = {val}
            result = search(new_domains)
            if result is not None:
                return result

        return None

    result = search(initial_domains)
    if result is None:
        print("No solution")
        return

    house = {c: [None] * 6 for c in cats}
    for c in cats:
        for v in values[c]:
            pos = next(iter(result[(c, v)]))
            house[c][pos] = v

    out = []
    for h in range(6):
        row = [house[c][h] for c in cats]
        out.append(f"House {h + 1}: " + ", ".join(row))

    print("\n".join(out))


