        ("house", "lunch", "spaghetti", 2),
        ("eq", "animal", "fish", "mother", "Holly"),
        ("house", "animal", "horse", 0),
        ("eq", "style", "mediterranean", "lunch", "stew"),
        ("house", "animal", "bird", 2),
        ("eq", "style", "colonial", "smoothie", "blueberry"),
        ("eq", "name", "Carol", "animal", "horse"),
        ("dist", "smoothie", "desert", "name", "Peter", 3),
        ("eq", "lunch", "grilled cheese", "smoothie", "dragonfruit"),
        ("gt", "lunch", "pizza", "smoothie", "dragonfruit"),
        ("lt", "mother", "Janelle", "name", "Arnold"),
        ("directly_left", "name", "Carol", "mother", "Aniya"),
        ("eq", "style", "ranch", "mother", "Aniya"),
        ("gt", "name", "Arnold", "style", "craftsman"),
        ("eq", "animal", "cat", "name", "Bob"),
        ("dist", "smoothie", "watermelon", "lunch", "pizza", 2),
        ("dist", "animal", "cat", "lunch", "stir fry", 3),
        ("eq", "name", "Arnold", "animal", "rabbit"),
        ("eq", "name", "Peter", "mother", "Janelle"),
    ]

    def constraint_categories(c):
        t = c[0]
        if t in ("house", "not_house"):
            cats = [c[1]]
        elif t == "dist":
            cats = [c[1], c[4]]
        else:
            cats = [c[1], c[3]]

        unique = []
        for cat in cats:
            if cat not in unique:
                unique.append(cat)
        return tuple(unique)

    constraints_by_cat = {cat: [] for cat in categories}
    for c in constraints:
        for cat in constraint_categories(c):
            constraints_by_cat[cat].append(c)

    def check(c, pos):
        t = c[0]

        if t == "house":
            _, cat, val, h = c
            if cat not in pos:
                return True
            return pos[cat][val] == h

        if t == "not_house":
            _, cat, val, h = c
            if cat not in pos:
                return True
            return pos[cat][val] != h

        if t == "dist":
            _, cat1, val1, cat2, val2, d = c
            if cat1 not in pos or cat2 not in pos:
                return True
            return abs(pos[cat1][val1] - pos[cat2][val2]) == d

        if t == "eq":
            _, cat1, val1, cat2, val2 = c
            if cat1 not in pos or cat2 not in pos:
                return True
            return pos[cat1][val1] == pos[cat2][val2]

        if t == "gt":
            _, cat1, val1, cat2, val2 = c
            if cat1 not in pos or cat2 not in pos:
                return True
            return pos[cat1][val1] > pos[cat2][val2]

        if t == "lt":
            _, cat1, val1, cat2, val2 = c
            if cat1 not in pos or cat2 not in pos:
                return True
            return pos[cat1][val1] < pos[cat2][val2]

        if t == "directly_left":
            _, cat1, val1, cat2, val2 = c
            if cat1 not in pos or cat2 not in pos:
                return True
            return pos[cat1][val1] + 1 == pos[cat2][val2]

        return True

    def add_fixed(fixed, val, h):
        if h < 0 or h >= 6:
            return False
        if val in fixed:
            return fixed[val] == h
        fixed[val] = h
        return True

    def generate_candidates(cat, pos):
        fixed = {}

        for c in constraints_by_cat[cat]:
            if c[0] == "house":
                _, _, val, h = c
                if not add_fixed(fixed, val, h):
                    return []

        for c in constraints_by_cat[cat]:
            t = c[0]

            if t == "eq":
                _, cat1, val1, cat2, val2 = c
                if cat1 == cat and cat2 in pos:
                    if not add_fixed(fixed, val1, pos[cat2][val2]):
                        return []
                elif cat2 == cat and cat1 in pos:
                    if not add_fixed(fixed, val2, pos[cat1][val1]):
                        return []

            elif t == "directly_left":
                _, cat1, val1, cat2, val2 = c
                if cat1 == cat and cat2 in pos:
                    if not add_fixed(fixed, val1, pos[cat2][val2] - 1):
                        return []
                elif cat2 == cat and cat1 in pos:
                    if not add_fixed(fixed, val2, pos[cat1][val1] + 1):
                        return []

        if len(set(fixed.values())) != len(fixed):
            return []

        for c in constraints_by_cat[cat]:
            if c[0] == "not_house":
                _, _, val, h = c
                if val in fixed and fixed[val] == h:
                    return []

        rem_vals = [v for v in values[cat] if v not in fixed]
        rem_houses = [h for h in range(6) if h not in fixed.values()]

        candidates = []
        for assign in itertools.permutations(rem_vals):
            perm = [None] * 6

            for v, h in fixed.items():
                perm[h] = v

            for h, v in zip(rem_houses, assign):
                perm[h] = v

            inv = {v: i for i, v in enumerate(perm)}
            temp = pos.copy()
            temp[cat] = inv

            if all(check(c, temp) for c in constraints_by_cat[cat]):
                candidates.append((tuple(perm), inv))

        return candidates

    def backtrack(pos):
        if len(pos) == len(categories):
            return all(check(c, pos) for c in constraints)

        best_cat = None
        best_candidates = None

        for cat in categories:
            if cat in pos:
                continue

            candidates = generate_candidates(cat, pos)

            if best_candidates is None or len(candidates) < len(best_candidates):
                best_cat = cat
                best_candidates = candidates
                if len(candidates) == 0:
                    return False

        for _, inv in best_candidates:
            pos[best_cat] = inv
            if backtrack(pos):
                return True
            del pos[best_cat]

