}


def valid(assignment):
    for cat in categories:
        seen = set()
        for v in assignment[cat]:
            if v is not None:
                if v in seen:
                    return False
                seen.add(v)

    for h in range(4):
        n = assignment["name"][h]
        a = assignment["animal"][h]
        e = assignment["education"][h]
        d = assignment["drink"][h]
        b = assignment["book"][h]
        m = assignment["month"][h]

        if n is not None:
