            return False

        if h == 1 and a == "horse":
            return False
        if h == 1 and e == "high school":
            return False

    def position(category, value):
        for i, v in enumerate(assignment[category]):
            if v == value:
                return i
        return None

    milk = position("drink", "milk")
    alice = position("name", "Alice")
    if milk is not None and alice is not None and abs(milk - alice) != 2:
        return False

    eric = position("name", "Eric")
    if eric is not None and milk is not None and milk != eric + 1:
        return False

    tea = position("drink", "tea")
    peter = position("name", "Peter")
    if tea is not None and peter is not None and tea >= peter:
        return False

    bachelor = position("education", "bachelor")
    january = position("month", "jan")
    if bachelor is not None and january is not None and bachelor <= january:
        return False

    return True


def solve():
    assignment = {cat: [None] * 4 for cat in categories}

    def backtrack():
        best = None

        for cat in categories:
            used = set(v for v in assignment[cat] if v is not None)
            for h in range(4):
                if assignment[cat][h] is not None:
                    continue

                candidates = []
                for val in domains[cat]:
                    if val in used:
                        continue

                    assignment[cat][h] = val
                    if valid(assignment):
                        candidates.append(val)
                    assignment[cat][h] = None

                if not candidates:
                    return False

                if best is None or len(candidates) < best[0]:
                    best = (len(candidates), cat, h, candidates)

        if best is None:
            return True

        _, cat, h, candidates = best
        for val in candidates:
            assignment[cat][h] = val
            if backtrack():
                return True
            assignment[cat][h] = None

        return False

    if not backtrack():
        return None

    lines = []
    for h in range(4):
        values = [assignment[cat][h] for cat in categories]
        lines.append(f"House {h + 1}: " + ", ".join(values))
    return "\n".join(lines)


