}

variable_names = []
for category in categories:
    for value in values[category]:
        variable_names.append(f"{category}:{value}")

domains = {name: set(range(5)) for name in variable_names}

domains["name:Bob"] = {4}
domains["flower:lilies"] = {2}
domains["hobby:knitting"] = {3}
domains["flower:carnations"].discard(1)

binary_constraints = [
    ("lunch:stew", "flower:tulips", "left"),
    ("vacation:camping", "lunch:grilled cheese", "eq"),
    ("hair:black", "name:Bob", "lt"),
    ("hobby:photography", "hair:gray", "eq"),
    ("lunch:pizza", "vacation:cruise", "eq"),
    ("name:Alice", "vacation:city", "eq"),
    ("vacation:beach", "hobby:painting", "left"),
    ("name:Arnold", "lunch:spaghetti", "eq"),
    ("hair:red", "lunch:spaghetti", "eq"),
    ("name:Eric", "hobby:gardening", "lt"),
    ("hobby:photography", "lunch:stew", "eq"),
    ("name:Eric", "flower:daffodils", "eq"),
    ("hair:brown", "hobby:painting", "left"),
    ("vacation:cruise", "hobby:knitting", "diff3"),
]


def support_first(d1, d2, rel):
    if rel == "eq":
        return d1 & d2
    if rel == "lt":
        return {x for x in d1 if any(y > x for y in d2)}
    if rel == "left":
        return {x for x in d1 if x + 1 in d2}
    if rel == "diff3":
        return {x for x in d1 if any(abs(x - y) == 3 for y in d2)}
    if rel == "neq":
        return {x for x in d1 if any(y != x for y in d2)}
    raise ValueError(rel)


def support_second(d1, d2, rel):
    if rel == "eq":
        return d2 & d1
    if rel == "lt":
        return {y for y in d2 if any(x < y for x in d1)}
    if rel == "left":
        return {y for y in d2 if y - 1 in d1}
    if rel == "diff3":
        return {y for y in d2 if any(abs(x - y) == 3 for x in d1)}
    if rel == "neq":
        return {y for y in d2 if any(x != y for x in d1)}
    raise ValueError(rel)


def propagate():
    while True:
        changed = False

        for v1, v2, rel in binary_constraints:
            new1 = support_first(domains[v1], domains[v2], rel)
            if new1 != domains[v1]:
                if not new1:
                    return False
                domains[v1] = new1
                changed = True

            new2 = support_second(domains[v1], domains[v2], rel)
            if new2 != domains[v2]:
                if not new2:
                    return False
                domains[v2] = new2
                changed = True

        for category in categories:
            cat_vars = [f"{category}:{value}" for value in values[category]]

            assigned_vals = set()
            for v in cat_vars:
                if len(domains[v]) == 1:
                    val = next(iter(domains[v]))
                    if val in assigned_vals:
                        return False
                    assigned_vals.add(val)

            for v in cat_vars:
                if len(domains[v]) > 1:
                    new = domains[v] - assigned_vals
                    if new != domains[v]:
                        if not new:
                            return False
                        domains[v] = new
                        changed = True

            for pos in range(5):
                candidates = [v for v in cat_vars if pos in domains[v]]
                if not candidates:
                    return False
                if len(candidates) == 1:
                    v = candidates[0]
                    if domains[v] != {pos}:
                        domains[v] = {pos}
                        changed = True

        if not changed:
            break

    return True


def search():
    if not propagate():
        return False

    unassigned = [(len(domains[v]), v) for v in variable_names if len(domains[v]) > 1]
    if not unassigned:
        return True

    unassigned.sort()
    _, var = unassigned[0]

    for val in sorted(domains[var]):
        backup = {k: set(d) for k, d in domains.items()}
        domains[var] = {val}

        if search():
            return True

        domains.clear()
        domains.update(backup)

    return False


if not search():
