import sys

def main():
    sys.setrecursionlimit(10000)

    names = ["Alice", "Carol", "Peter", "Bob", "Arnold", "Eric"]
    flowers = ["carnations", "iris", "tulips", "daffodils", "lilies", "roses"]
    vacations = ["camping", "mountain", "city", "beach", "cultural", "cruise"]
    styles = ["colonial", "modern", "mediterranean", "craftsman", "ranch", "victorian"]
    heights = ["short", "very short", "average", "tall", "super tall", "very tall"]
    hairs = ["red", "black", "gray", "brown", "auburn", "blonde"]

    categories = [
        ("name", names),
        ("flower", flowers),
        ("vacation", vacations),
        ("style", styles),
        ("height", heights),
        ("hair", hairs),
    ]

    items = [(cat, val) for cat, vals in categories for val in vals]

    class UnionFind:
        def __init__(self, items):
            self.parent = {item: item for item in items}

        def find(self, x):
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x

        def union(self, a, b):
            ra = self.find(a)
            rb = self.find(b)
            if ra != rb:
                self.parent[rb] = ra

    uf = UnionFind(items)

    equal_pairs = [
        (("height", "very short"), ("hair", "auburn")),
        (("name", "Arnold"), ("vacation", "camping")),
        (("hair", "auburn"), ("name", "Eric")),
        (("style", "craftsman"), ("name", "Bob")),
        (("height", "very tall"), ("name", "Bob")),
        (("vacation", "city"), ("height", "short")),
        (("flower", "carnations"), ("hair", "brown")),
        (("hair", "red"), ("flower", "lilies")),
        (("vacation", "mountain"), ("style", "victorian")),
        (("flower", "daffodils"), ("style", "modern")),
        (("name", "Arnold"), ("height", "average")),
        (("height", "very tall"), ("vacation", "cultural")),
        (("style", "mediterranean"), ("hair", "red")),
        (("height", "super tall"), ("hair", "black")),
        (("name", "Eric"), ("flower", "roses")),
    ]

    for a, b in equal_pairs:
        uf.union(a, b)

    comp_index = {}
    comp_of = {}
    for item in items:
        r = uf.find(item)
        if r not in comp_index:
            comp_index[r] = len(comp_index)
        comp_of[item] = comp_index[r]

    n = len(comp_index)
    domains = [set(range(6)) for _ in range(n)]

    def comp(cat, val):
        return comp_of[(cat, val)]

    unary_not = [
        (("flower", "lilies"), 4),
        (("style", "modern"), 3),
        (("style", "mediterranean"), 0),
        (("height", "tall"), 4),
        (("flower", "tulips"), 3),
    ]

    for (cat, val), pos in unary_not:
        domains[comp(cat, val)].discard(pos)
        if not domains[comp(cat, val)]:
            sys.exit(1)

    arcs = []

    def add_arc(i, j, func):
        arcs.append((i, j, func))

    binary_specs = [
        ("lt", ("vacation", "cultural"), ("height", "super tall")),
        ("lt", ("height", "tall"), ("hair", "brown")),
        ("lt", ("height", "very short"), ("hair", "blonde")),
        ("lt", ("style", "colonial"), ("flower", "tulips")),
        ("direct_left", ("name", "Carol"), ("name", "Bob")),
        ("direct_left", ("vacation", "mountain"), ("vacation", "cruise")),
        ("dist2", ("hair", "gray"), ("height", "short")),
        ("dist2", ("flower", "roses"), ("name", "Peter")),
    ]

    for rel, va, vb in binary_specs:
        a = comp(va[0], va[1])
        b = comp(vb[0], vb[1])

        if a == b:
            if rel in ("lt", "direct_left", "dist2"):
                domains[a].clear()
            continue

        if rel == "lt":
            add_arc(a, b, lambda x, y: x < y)
            add_arc(b, a, lambda x, y: y < x)
        elif rel == "direct_left":
            add_arc(a, b, lambda x, y: x + 1 == y)
            add_arc(b, a, lambda x, y: y + 1 == x)
        elif rel == "dist2":
            add_arc(a, b, lambda x, y: abs(x - y) == 3)
            add_arc(b, a, lambda x, y: abs(x - y) == 3)

    cat_comps = {cat: [] for cat, _ in categories}
    for cat, vals in categories:
        for val in vals:
            cat_comps[cat].append(comp(cat, val))

    for cat, comps in cat_comps.items():
        uniq = []
        for c in comps:
            if c not in uniq:
                uniq.append(c)

        if len(uniq) != 6:
            sys.exit(1)

        for i in range(len(uniq)):
            for j in range(i + 1, len(uniq)):
                a, b = uniq[i], uniq[j]
                add_arc(a, b, lambda x, y: x != y)
                add_arc(b, a, lambda x, y: x != y)

    degree = [0] * n
    for i, j, _ in arcs:
        degree[i] += 1
        degree[j] += 1

    def ac3(domains):
        queue = list(arcs)

        while queue:
            i, j, func = queue.pop()
            di = domains[i]
            dj = domains[j]

            if not di or not dj:
                return False

            new_di = set()
            for x in di:
                supported = False
                for y in dj:
                    if func(x, y):
                        supported = True
                        break
                if supported:
                    new_di.add(x)

            if new_di != di:
                if not new_di:
                    return False
                domains[i] = new_di

                for k, l, func2 in arcs:
                    if l == i and k != j:
                        queue.append((k, i, func2))

        return True

    def search(domains):
        if any(len(d) == 0 for d in domains):
            return None

        unassigned = [i for i in range(n) if len(domains[i]) > 1]
        if not unassigned:
            for i, j, func in arcs:
                x = next(iter(domains[i]))
                y = next(iter(domains[j]))
                if not func(x, y):
                    return None
            return domains

        var = min(unassigned, key=lambda i: (len(domains[i]), -degree[i]))

        for val in sorted(domains[var]):
            new_domains = [set(d) for d in domains]
            new_domains[var] = {val}

            if ac3(new_domains):
                result = search(new_domains)
                if result is not None:
                    return result

        return None

    if not ac3(domains):
        sys.exit(1)

    solution = search(domains)
    if solution is None:
        sys.exit(1)

    house_attrs = [{} for _ in range(6)]
    for (cat, val), c in comp_of.items():
        pos = next(iter(solution[c]))
        house_attrs[pos][cat] = val

    order = ["name", "flower", "vacation", "style", "height", "hair"]
    output_lines = []

    for pos in range(6):
        row = [house_attrs[pos][cat] for cat in order]
        output_lines.append(f"House {pos + 1}: " + ", ".join(row))

    sys.stdout.write("\n".join(output_lines))

if __name__ == "__main__":
    main()

