import sys
from collections import deque

N = 6

names = ["Peter", "Bob", "Eric", "Carol", "Alice", "Arnold"]
animals = ["rabbit", "dog", "horse", "fish", "bird", "cat"]
sports = ["basketball", "swimming", "tennis", "soccer", "baseball", "volleyball"]
hair = ["blonde", "gray", "auburn", "red", "black", "brown"]
heights = ["average", "very short", "very tall", "tall", "super tall", "short"]
cigars = ["pall mall", "yellow monster", "blue master", "prince", "dunhill", "blends"]

categories = {
    "name": names,
    "animal": animals,
    "sport": sports,
    "hair": hair,
    "height": heights,
    "cigar": cigars,
}

all_vars = [(cat, val) for cat, vals in categories.items() for val in vals]
category_vars = {cat: [(cat, val) for val in vals] for cat, vals in categories.items()}

domains = {v: set(range(N)) for v in all_vars}
unary_not = {}

def add_not(var, pos):
    unary_not.setdefault(var, set()).add(pos)

add_not(("height", "very short"), 4)
add_not(("height", "super tall"), 4)
add_not(("sport", "tennis"), 2)
add_not(("animal", "horse"), 4)

for var, pos in unary_not.items():
    domains[var].discard(pos)

REL_ALLOWED = {
    "eq": {(i, i) for i in range(N)},
    "neq": {(i, j) for i in range(N) for j in range(N) if i != j},
    "lt": {(i, j) for i in range(N) for j in range(N) if i < j},
    "gt": {(i, j) for i in range(N) for j in range(N) if i > j},
    "left": {(i, j) for i in range(N) for j in range(N) if j == i + 1},
    "dist1": {(i, j) for i in range(N) for j in range(N) if abs(i - j) == 1},
    "dist2": {(i, j) for i in range(N) for j in range(N) if abs(i - j) == 2},
    "dist3": {(i, j) for i in range(N) for j in range(N) if abs(i - j) == 3},
}

binary_constraints = []
initial_arcs = []
arc_set = set()
neighbors = {v: [] for v in all_vars}

def add_bin(a, b, rel):
    binary_constraints.append((a, b, rel))
    arc_ab = (a, b, rel, True)
    arc_ba = (b, a, rel, False)
    if arc_ab not in arc_set:
        arc_set.add(arc_ab)
        initial_arcs.append(arc_ab)
        neighbors[b].append(arc_ab)
    if arc_ba not in arc_set:
        arc_set.add(arc_ba)
        initial_arcs.append(arc_ba)
        neighbors[a].append(arc_ba)

for cat, cat_vars in category_vars.items():
    for i in range(len(cat_vars)):
        for j in range(i + 1, len(cat_vars)):
            add_bin(cat_vars[i], cat_vars[j], "neq")

add_bin(("height", "very tall"), ("animal", "dog"), "dist1")
add_bin(("sport", "tennis"), ("height", "average"), "dist3")
add_bin(("animal", "cat"), ("sport", "baseball"), "eq")
add_bin(("animal", "fish"), ("hair", "red"), "dist2")
add_bin(("animal", "cat"), ("cigar", "dunhill"), "lt")
add_bin(("animal", "rabbit"), ("height", "super tall"), "lt")
add_bin(("name", "Alice"), ("cigar", "dunhill"), "eq")
add_bin(("hair", "red"), ("cigar", "dunhill"), "eq")
add_bin(("cigar", "prince"), ("cigar", "yellow monster"), "lt")
add_bin(("sport", "volleyball"), ("cigar", "yellow monster"), "gt")
add_bin(("cigar", "blue master"), ("hair", "black"), "left")
add_bin(("sport", "basketball"), ("cigar", "blue master"), "dist2")
add_bin(("cigar", "yellow monster"), ("height", "tall"), "eq")
add_bin(("name", "Bob"), ("animal", "fish"), "dist1")
add_bin(("cigar", "dunhill"), ("sport", "soccer"), "eq")
add_bin(("name", "Arnold"), ("cigar", "blends"), "eq")
add_bin(("name", "Peter"), ("cigar", "prince"), "eq")
add_bin(("hair", "blonde"), ("height", "tall"), "dist2")
add_bin(("sport", "swimming"), ("name", "Alice"), "left")
add_bin(("name", "Eric"), ("height", "super tall"), "eq")
add_bin(("height", "short"), ("animal", "rabbit"), "eq")
add_bin(("animal", "cat"), ("hair", "brown"), "dist1")
add_bin(("height", "short"), ("hair", "auburn"), "dist1")

hall_sets = {}
for cat, cat_vars in category_vars.items():
    sets = []
    for mask in range(1, 1 << N):
        idxs = [i for i in range(N) if mask & (1 << i)]
        subset_set = set(cat_vars[i] for i in idxs)
        outside = [v for v in cat_vars if v not in subset_set]
        sets.append((idxs, subset_set, outside))
    hall_sets[cat] = sets

def revise(domains, arc):
    v1, v2, rel, v1_is_first = arc
    d1 = domains[v1]
    d2 = domains[v2]
    allowed = REL_ALLOWED[rel]
    new = set()

    if v1_is_first:
        for x in d1:
            for y in d2:
                if (x, y) in allowed:
                    new.add(x)
                    break
    else:
        for x in d1:
            for y in d2:
                if (y, x) in allowed:
                    new.add(x)
                    break

    if new != d1:
        domains[v1] = new
        return True
    return False

def ac3(domains):
    for d in domains.values():
        if not d:
            return False

    queue = deque(initial_arcs)
    in_queue = set(initial_arcs)

    while queue:
        arc = queue.popleft()
        in_queue.remove(arc)

        if revise(domains, arc):
            if not domains[arc[0]]:
                return False
            for nxt in neighbors[arc[0]]:
                if nxt not in in_queue:
                    queue.append(nxt)
                    in_queue.add(nxt)

    return True

def enforce_all_diff(domains):
    changed = False

    for cat, cat_vars in category_vars.items():
        for idxs, subset_set, outside in hall_sets[cat]:
            union = set()
            for i in idxs:
                union |= domains[cat_vars[i]]

            k = len(idxs)
            if len(union) < k:
                return False

            if len(union) == k:
                for v in outside:
                    old = domains[v]
                    new = old - union
                    if new != old:
                        domains[v] = new
                        changed = True
                        if not new:
                            return False

    return changed

def propagate(domains):
    while True:
        if not ac3(domains):
            return False
        if not enforce_all_diff(domains):
            return True

def choose_var(domains):
    best = None
    best_size = N + 1
    best_degree = -1

    for v in all_vars:
        size = len(domains[v])
        if size == 1:
            continue
        degree = len(neighbors[v])
        if size < best_size or (size == best_size and degree > best_degree):
            best = v
            best_size = size
            best_degree = degree

    return best

def verify(domains):
    for v in all_vars:
        if len(domains[v]) != 1:
            return False

    for a, b, rel in binary_constraints:
        x = next(iter(domains[a]))
        y = next(iter(domains[b]))
        if (x, y) not in REL_ALLOWED[rel]:
            return False

    for v, forbidden in unary_not.items():
        if next(iter(domains[v])) in forbidden:
            return False

    for cat, cat_vars in category_vars.items():
        positions = [next(iter(domains[v])) for v in cat_vars]
        if len(set(positions)) != N:
            return False

    return True

def solve(domains):
    var = choose_var(domains)
    if var is None:
        return domains if verify(domains) else None

    for val in sorted(domains[var]):
        new_domains = {v: set(d) for v, d in domains.items()}
        new_domains[var] = {val}

        if propagate(new_domains):
            result = solve(new_domains)
            if result is not None:
                return result

    return None

sys.setrecursionlimit(10000)

if not propagate(domains):
    sys.exit(1)

solution = solve(domains)
if solution is None:
    sys.exit(1)

house_attrs = {h: {} for h in range(N)}
for (cat, val), dom in solution.items():
    pos = next(iter(dom))
    house_attrs[pos][cat] = val

lines = []
for h in range(N):
    attrs = [
        house_attrs[h]["name"],
        house_attrs[h]["animal"],
        house_attrs[h]["sport"],
        house_attrs[h]["hair"],
        house_attrs[h]["height"],
        house_attrs[h]["cigar"],
    ]
    lines.append(f"House {h + 1}: " + ", ".join(attrs))

print("\n".join(lines))

