    if smoothie_assignment[name_pos["Arnold"]] != "cherry":
        return False

    return True

for name_assignment in itertools.permutations(names):
    for smoothie_assignment in itertools.permutations(smoothies):
        if is_valid(name_assignment, smoothie_assignment):
            for i in range(5):
                print(f"House {i + 1}: {name_assignment[i]}, {smoothie_assignment[i]}")
            raise SystemExit

import itertools


def solve():
    names = ['Peter', 'Eric', 'Alice', 'Carol', 'Bob', 'Arnold']
    animals = ['horse', 'fish', 'cat', 'bird', 'dog', 'rabbit']
    months = ['sept', 'mar', 'jan', 'feb', 'april', 'may']
    mothers = ['Holly', 'Sarah', 'Penny', 'Kailyn', 'Aniya', 'Janelle']
    vacations = ['beach', 'cruise', 'cultural', 'camping', 'city', 'mountain']

    def add_fixed(d, pos, val):
        if pos in d:
            return d[pos] == val
        d[pos] = val
        return True

    valid_months = []
    for m in itertools.permutations(months):
        if m[1] != 'feb':
            continue
        may_pos = m.index('may')
        mar_pos = m.index('mar')
        if abs(mar_pos - may_pos) != 3:
            continue
        valid_months.append(m)

    valid_names = []
    for n in itertools.permutations(names):
        if n[1] == 'Carol' and n[0] != 'Eric':
            valid_names.append(n)

    for m in valid_months:
        may_pos = m.index('may')
        april_pos = m.index('april')
        sept_pos = m.index('sept')

        for n in valid_names:
            if n[may_pos] != 'Bob':
                continue

            fixed_a = {}
            if not add_fixed(fixed_a, 1, 'fish'):
                continue
            if not add_fixed(fixed_a, may_pos, 'rabbit'):
                continue
            if not add_fixed(fixed_a, april_pos, 'dog'):
                continue

            horse_pos = april_pos + 1
            if horse_pos >= 6:
                continue
            if not add_fixed(fixed_a, horse_pos, 'horse'):
                continue
            if len(set(fixed_a.values())) != len(fixed_a):
                continue

            rem_a_vals = [x for x in animals if x not in fixed_a.values()]
            rem_a_pos = [i for i in range(6) if i not in fixed_a]

            for rem_a in itertools.permutations(rem_a_vals, len(rem_a_pos)):
                a = [None] * 6
                for pos, val in fixed_a.items():
                    a[pos] = val
                for pos, val in zip(rem_a_pos, rem_a):
                    a[pos] = val

                cat_pos = a.index('cat')

                fixed_m = {}
                if not add_fixed(fixed_m, 1, 'Janelle'):
                    continue
                if not add_fixed(fixed_m, 3, 'Kailyn'):
                    continue

                alice_pos = n.index('Alice')
                if not add_fixed(fixed_m, alice_pos, 'Aniya'):
                    continue
                if not add_fixed(fixed_m, cat_pos, 'Holly'):
                    continue
                if len(set(fixed_m.values())) != len(fixed_m):
                    continue

                rem_m_vals = [x for x in mothers if x not in fixed_m.values()]
                rem_m_pos = [i for i in range(6) if i not in fixed_m]

                for rem_m in itertools.permutations(rem_m_vals, len(rem_m_pos)):
                    mo = [None] * 6
                    for pos, val in fixed_m.items():
                        mo[pos] = val
                    for pos, val in zip(rem_m_pos, rem_m):
                        mo[pos] = val

                    penny_pos = mo.index('Penny')
                    if not (penny_pos < may_pos):
                        continue

                    sarah_pos = mo.index('Sarah')
                    if abs(sarah_pos - may_pos) != 1:
                        continue

                    fixed_v = {}
                    if not add_fixed(fixed_v, 5, 'cruise'):
                        continue

                    peter_pos = n.index('Peter')
                    if not add_fixed(fixed_v, peter_pos, 'beach'):
                        continue
                    if not add_fixed(fixed_v, cat_pos, 'camping'):
                        continue
                    if not add_fixed(fixed_v, sept_pos, 'city'):
                        continue
                    if len(set(fixed_v.values())) != len(fixed_v):
                        continue

                    rem_v_vals = [x for x in vacations if x not in fixed_v.values()]
                    rem_v_pos = [i for i in range(6) if i not in fixed_v]

                    for rem_v in itertools.permutations(rem_v_vals, len(rem_v_pos)):
                        v = [None] * 6
                        for pos, val in fixed_v.items():
                            v[pos] = val
                        for pos, val in zip(rem_v_pos, rem_v):
                            v[pos] = val

                        cultural_pos = v.index('cultural')
                        if cultural_pos < may_pos:
                            return (n, a, m, mo, v)

    return None


def main():
    sol = solve()
    if sol is None:
        return

    name, animal, month, mother, vacation = sol
    for i in range(6):
        print(f"House {i + 1}: {name[i]}, {animal[i]}, {month[i]}, {mother[i]}, {vacation[i]}")


if __name__ == "__main__":
    main()
